'use strict';

function trim(s) {
  return s.trim();
}

function capitalize(str) {
  if (!str) return str;
  return str[0].toUpperCase() + str.slice(1);
}

function reverse(str) {
  return [...str].reverse().join('');
}

module.exports = { trim, capitalize, reverse };

'use strict';

const test = require('node:test');
const assert = require('node:assert');
const { trim, capitalize, reverse } = require('../src/str');

test('trim', () => {
  assert.strictEqual(trim('  a  '), 'a');
});

test('capitalize', () => {
  assert.strictEqual(capitalize('abc'), 'Abc');
  assert.strictEqual(capitalize('Abc'), 'Abc');
  assert.strictEqual(capitalize('a'), 'A');
  assert.strictEqual(capitalize(''), '');
});

test('reverse', () => {
  assert.strictEqual(reverse('abc'), 'cba');
  assert.strictEqual(reverse('a'), 'a');
  assert.strictEqual(reverse(''), '');
});

